import {makePathBoard,connectedPath} from '../logic.js';import {gameFrame,roundFlow} from '../ui.js';
function tileSVG(connections){const ends={N:[32,0],S:[32,64],E:[64,32],W:[0,32]};return `<svg viewBox="0 0 64 64" aria-hidden="true">${[...connections].map(d=>`<path d="M32 32L${ends[d].join(' ')}" stroke="#27866f" stroke-width="12" stroke-linecap="round"/>`).join('')}<circle cx="32" cy="32" r="6" fill="#27866f"/></svg>`;}
export function mountGame(root,c){const flow=roundFlow(root,c),size=c.difficulty==='easy'?3:c.difficulty==='hard'?5:4;function next(){flow.next();const r=makePathBoard(size);let selected=null;const area=gameFrame(root,'Connect the entrance to the exit','Select two tiles to swap. The green path must meet at every connection.');area.innerHTML=`<p class="path-endpoints">Enter: row ${Math.floor(r.start/size)+1}, left · Exit: row ${Math.floor(r.end/size)+1}, right</p><div class="tile-grid path-board" style="--cols:${size}"></div><div class="choice-row"><button class="primary" id="check">Check path</button>${c.mode==='learn'?'<button id="reveal">Show solution</button>':''}</div>`;const grid=area.querySelector('.tile-grid');function draw(){grid.innerHTML=r.tiles.map((tile,i)=>`<button class="path-tile ${i===r.start?'entrance':''} ${i===r.end?'exit':''}" data-i="${i}" aria-pressed="${selected===i}" aria-label="Row ${Math.floor(i/size)+1}, column ${i%size+1}, connects ${[...tile].map(d=>({N:'north',E:'east',S:'south',W:'west'}[d])).join(' and ')}">${tileSVG(tile)}</button>`).join('');grid.querySelectorAll('button').forEach(b=>b.onclick=()=>{const i=+b.dataset.i;if(selected===null)selected=i;else{[r.tiles[selected],r.tiles[i]]=[r.tiles[i],r.tiles[selected]];selected=null;}draw();grid.querySelector(`[data-i="${i}"]`).focus();});}draw();area.querySelector('#check').onclick=()=>{const correct=connectedPath(r.tiles,size,r.start,r.end);if(!correct){flow.answer(false,'The path has a gap. Study a complete connection before the next board.',next);r.tiles=[...r.solution];draw();grid.querySelectorAll('button').forEach(b=>b.disabled=true);}else flow.answer(true,'You connected the entrance and exit.',next);};area.querySelector('#reveal')?.addEventListener('click',()=>{flow.answer(false,'Solution shown. This round is recorded as assisted, not correct.',next);r.tiles=[...r.solution];draw();grid.querySelectorAll('button').forEach(b=>b.disabled=true);});}next();return {dispose(){}};}
